def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    alive = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)

    if budget <= 0:
        return 0.0

    if not alive:
        bid = min(budget, DAILY_SALARY * 0.35)
        return max(0.0, float(bid))

    prev_bids = []
    desperate_count = 0
    rich_count = 0
    for opp in alive:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            prev_bids.append(float(prev['bid']))
        if opp.get('hp', 0) <= 3 or opp.get('no_water_days', 0) >= 1:
            desperate_count += 1
        if opp.get('budget', 0) >= 300:
            rich_count += 1

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    tight_supply = supply <= 17
    abundant_supply = supply >= 22
    urgent_me = hp <= 3 or no_water >= 1
    very_urgent_me = hp <= 2 or no_water >= 2

    if very_urgent_me:
        base = max(DAILY_SALARY * 1.05, highest_prev + 2.5)
    elif urgent_me:
        base = max(DAILY_SALARY * 0.9, avg_prev + 2.0)
    else:
        if abundant_supply:
            base = DAILY_SALARY * 0.42
        elif tight_supply:
            base = DAILY_SALARY * 0.62
        else:
            base = DAILY_SALARY * 0.52

        if highest_prev >= 105:
            base = min(base, DAILY_SALARY * 0.5)
        elif highest_prev >= 90:
            base = max(base, DAILY_SALARY * 0.58)
        elif highest_prev > 0:
            base = max(base, min(highest_prev + 1.25, DAILY_SALARY * 0.82))

    if desperate_count >= 2:
        base += 6.0
    elif desperate_count == 1:
        base += 3.0

    if rich_count >= 2 and not urgent_me:
        base -= 4.0

    remaining_days = max(1, 10 - int(day) + 1)
    reserve_target = max(0.0, remaining_days * DAILY_SALARY * 0.45)
    spend_cap = budget
    if not urgent_me:
        spend_cap = max(0.0, budget - reserve_target)
        spend_cap = max(DAILY_SALARY * 0.35, spend_cap)

    if abundant_supply and not urgent_me:
        base *= 0.92
    if tight_supply:
        base *= 1.08

    bid = min(budget, min(base, spend_cap))

    floor_bid = 0.0
    if very_urgent_me:
        floor_bid = min(budget, DAILY_SALARY * 0.85)
    elif urgent_me:
        floor_bid = min(budget, DAILY_SALARY * 0.72)
    else:
        floor_bid = min(budget, DAILY_SALARY * 0.28)

    bid = max(floor_bid, bid)
    bid = max(0.0, min(float(bid), float(budget)))
    return bid

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    EPISODE_DAYS = 10

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    if not alive_opponents:
        return min(my_status['budget'], 1)

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    base_bid = DAILY_SALARY * 0.55

    if my_status['hp'] <= 2 or my_status['no_water_days'] >= 1:
        base_bid = DAILY_SALARY * 0.95
    elif my_status['hp'] <= 4:
        base_bid = DAILY_SALARY * 0.75

    if yesterday_bids:
        max_prev_opp_bid = max(yesterday_bids)

        if max_prev_opp_bid >= DAILY_SALARY * 0.8 and my_status['hp'] > 2:
            base_bid = max(base_bid, max_prev_opp_bid + 5)
        elif max_prev_opp_bid < DAILY_SALARY * 0.4 and my_status['hp'] > 4:
            base_bid = min(base_bid, max_prev_opp_bid + 1)

    sum_opp_water_req = sum([o['water_requirement'] for o in alive_opponents])
    estimated_total_water_needed = sum_opp_water_req + WATER_REQ

    if day_context['supply'] < estimated_total_water_needed:
        if base_bid < DAILY_SALARY * 0.8:
            base_bid *= 1.1
    elif day_context['supply'] > estimated_total_water_needed * 1.5:
        if my_status['hp'] > 4 and base_bid > DAILY_SALARY * 0.3:
            base_bid *= 0.9

    bid = min(base_bid, my_status['budget'])
    bid = min(bid, DAILY_SALARY * 1.05)
    bid = max(bid, 1)

    return bid
